Boolean out_fifo_insert( Out_Fifo out_fifo , Out_Func out_func , UInt32 t_offset ,  UInt32 t_on , UInt32 t_off  , UInt16 pulse , UInt16 frame_count)
{
    Out_Fifo_Node *node = (Out_Fifo_Node*)fifo_remove( out_fifo->q_f );

    if( !node )return FALSE ;

    node->frame.t_on      = t_on       ; 
    node->frame.t_off     = t_off      ;
    node->frame.t_offset  = t_offset   ;
    node->frame.pulse     = pulse      ;
    node->frame_count     = frame_count;    
	node->out_func        = out_func   ;

    fifo_insert( out_fifo->q_p , (Fifo_Node*)node );

    return TRUE ;
}

